#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="tizen/.wizard-state.env"
CONFIG_XML="tizen/config.xml"
PLACEHOLDER="NErITV001"
CHECKLIST_RESULTS=()

banner "Samsung Tizen TV Platform App — package, sign, verify (ticket #99)"
say "This repo's web app is already hosted and reused as-is (docs/tizen-entry.html)."
say "This wizard covers only what's left: Tizen Studio setup, signing, building the"
say "package, running it on the emulator/real hardware, and recording what you"
say "actually observe — none of which an agent can do from a sandboxed shell."

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Install Tizen Studio + TV Extension + Samsung Certificate Extension"
say "Skip this stage entirely if Tizen Studio is already installed with the TV"
say "Extension and Samsung Certificate Extension."
step "Download/install Tizen Studio for your OS from Samsung's official docs:"
open_url "https://developer.samsung.com/smarttv/develop/getting-started/setting-up-sdk/installing-sdk.html"
step "In Tizen Studio, open Package Manager and install the 'TV Extension'."
step "Also install the 'Samsung Certificate Extension' (same Package Manager screen,"
step "  or via Tools > Certificate Manager if it prompts you to install it there)."
note "Exact menu wording drifts between Tizen Studio releases — if a label here"
note "doesn't match what you see, the Package Manager search box finds it by name."
pause "Done (or already installed)? Press Enter to continue."

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Create a signing certificate profile"
say "Tizen requires every installed app to be signed with an author certificate"
say "plus a Samsung distributor certificate, tied to a 10-character package id"
say "that only this certificate profile can sign."
step "In Tizen Studio: Tools > Certificate Manager."
step "Create a new profile: generate/import an author certificate, then add a"
step "  Samsung distributor certificate (requires a free Samsung account — sign in"
step "  when prompted)."
step "Finish the wizard. Tizen Studio shows the package id this profile issues"
step "  (10 alphanumeric characters, e.g. 'aB3dE5fG7h') — copy it."
note "If you already have a profile from a previous Tizen project, you can reuse"
note "its package id instead of creating a new one."
while true; do
  ask PACKAGE_ID "Paste the 10-character package id this profile issued:"
  if [[ "$PACKAGE_ID" =~ ^[A-Za-z0-9]{10}$ ]]; then
    break
  fi
  warn "'$PACKAGE_ID' isn't exactly 10 alphanumeric characters — try again."
done
write_env PACKAGE_ID "$PACKAGE_ID"
ask PROFILE_NAME "What did you name this signing profile in Certificate Manager?"
write_env PROFILE_NAME "$PROFILE_NAME"

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Point config.xml at your real package id"
say "$CONFIG_XML currently has a placeholder ('$PLACEHOLDER') in two spots:"
say "the tizen:application id and package attributes — see the comment at the"
say "top of that file explaining why."
if grep -q "$PLACEHOLDER" "$CONFIG_XML" 2>/dev/null; then
  note "Found $(grep -c "$PLACEHOLDER" "$CONFIG_XML") occurrence(s) of '$PLACEHOLDER' in $CONFIG_XML."
  if confirm "Replace them with '$PACKAGE_ID' now?"; then
    sed -i.bak "s/$PLACEHOLDER/$PACKAGE_ID/g" "$CONFIG_XML" && rm -f "$CONFIG_XML.bak"
    printf '  %s✓ updated%s %s\n' "$GREEN" "$RESET" "$CONFIG_XML"
  else
    warn "Skipped — edit $CONFIG_XML by hand before building."
    SKIPPED+=("replace $PLACEHOLDER in $CONFIG_XML with $PACKAGE_ID")
  fi
else
  note "No '$PLACEHOLDER' left in $CONFIG_XML — looks like this was already done."
fi

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Build and sign the .wgt package"
warn "The exact tizen-cli flags below can drift between Tizen Studio versions —"
warn "confirm against 'tizen package --help' or Samsung's CLI docs before trusting them."
open_url "https://developer.samsung.com/smarttv/develop/getting-started/using-cli/building-and-signing.html"
say "From the repo root, with the tizen CLI on your PATH:"
step "tizen build-web -- tizen/ -out tizen/.buildResult"
step "tizen package -t wgt -s \"$PROFILE_NAME\" -- tizen/.buildResult"
note "This produces a signed .wgt file (printed in the command's own output)."
pause "Built and signed? Press Enter to continue."

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Install and launch on the Tizen TV Emulator"
step "Tizen Studio > Tools > Device Manager > create/launch a TV emulator image"
step "  (TV Extension profile) if you don't already have one running."
step "Find its device id: tizen list (or Device Manager's own listing)."
say "Then, from the repo root:"
step "tizen install -n <path-to-.wgt> -t <emulator-device-id>"
step "tizen run -p $PACKAGE_ID -t <emulator-device-id>"
pause "App installed and running in the emulator? Press Enter to continue."

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "Hand-verify feature parity"
say "Using the emulator's remote-control panel (or a real Samsung TV in Developer"
say "Mode, if you have one — optional, skip any you can't test):"
_check() {
  local label="$1"
  if confirm "$label — works?"; then
    CHECKLIST_RESULTS+=("- [x] $label")
  else
    CHECKLIST_RESULTS+=("- [ ] $label — NOT confirmed working")
    warn "Marked as not confirmed — fix before store submission."
  fi
}
_check "D-pad moves focus between Channel/Live event rows"
_check "Disabled Channel rows (nothing scheduled) are skipped by D-pad navigation"
_check "OK/Enter tunes the focused row exactly like clicking it on the web app"
_check "Remote Back button closes an open guide panel"
_check "Favorites: marking/unmarking works and the Favorites section updates"
_check "Live event rows appear/disappear and tune correctly"
_check "Language toggle switches chrome text and persists"
_check "Go to Live resumes playback at the right position — the live broadcast position for a Channel, the live edge for a Live event"
_check "Mute/unmute works"
if confirm "Did you also test on a real Samsung TV in Developer Mode (optional)?"
then
  REAL_HARDWARE="yes"
else
  REAL_HARDWARE="no (emulator only)"
fi

# ── Stage 7 ────────────────────────────────────────────────────────────────
stage "Record the three flagged research unknowns"
say "Spec #98 flagged these as real per-platform unknowns with no documented"
say "answer — type exactly what you observed, not what you expect."
ask OBS_DPAD_FOCUS "D-pad hardware focus behavior — what did you see?"
ask OBS_BACKGROUND_SUSPEND "Background/suspend playback behavior — what did you see?"
ask OBS_AUTOPLAY "Autoplay policy — did playback require a user gesture?"

# ── Stage 8 ────────────────────────────────────────────────────────────────
stage "Write tizen/emulator-observations.md"
OBS_FILE="tizen/emulator-observations.md"
{
  printf '# Tizen emulator/hardware observations\n\n'
  printf 'Recorded: %s\n' "$(date +%Y-%m-%d)"
  printf 'Package id: %s\n' "$PACKAGE_ID"
  printf 'Tested on real hardware: %s\n\n' "$REAL_HARDWARE"
  printf '## Feature-parity checklist\n\n'
  for line in "${CHECKLIST_RESULTS[@]}"; do printf '%s\n' "$line"; done
  printf '\n## Flagged research unknowns\n\n'
  printf -- '- **D-pad hardware focus behavior:** %s\n' "$OBS_DPAD_FOCUS"
  printf -- '- **Background/suspend playback behavior:** %s\n' "$OBS_BACKGROUND_SUSPEND"
  printf -- '- **Autoplay policy:** %s\n' "$OBS_AUTOPLAY"
} > "$OBS_FILE"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$OBS_FILE"
note "Commit this file — it's the acceptance-criteria record of what was actually"
note "observed, not a guess."

finish
}

run_wizard "$@"; exit
